'use strict';
let supportWindowKind='active';
const supportActiveText=weaponSkillText;
weaponSkillText=function(id){if(!SUPPORT_SKILLS[id])return supportActiveText(id);const d=SUPPORT_SKILLS[id],format=rank=>d.detail.replace(/\{(\w+)\}/g,(_,key)=>Number(supportValue(d,key,rank).toFixed(2)));return supportSkillText(id)+'\n\nLv.1: '+format(1)+'\nLv.30: '+format(30)};
function supportTabs(body){const tabs=document.createElement('div');tabs.className='support-tabs';for(const [kind,title]of [['active','Active'],['buff','Buff'],['passive','Passive']]){const b=document.createElement('button');b.textContent=title;b.classList.toggle('selected',supportWindowKind===kind);b.setAttribute('aria-pressed',String(supportWindowKind===kind));b.onclick=()=>{supportWindowKind=kind;renderSwordSkillWindow(body)};tabs.append(b)}body.prepend(tabs)}
const supportActiveWindow=renderSwordSkillWindow;
renderSwordSkillWindow=function(body){if(supportWindowKind==='active'){supportActiveWindow(body);supportTabs(body);$('modalTitle').textContent='ชุดสกิล · Active / Buff / Passive';return}ensureBaselineSkills(player);body.replaceChildren();body.className='weapon-skill-window';$('modalTitle').textContent='ชุดสกิล · Active / Buff / Passive';const grid=document.createElement('div');grid.className='support-loadout';for(let tier=1;tier<=4;tier++){const row=document.createElement('section');row.className='support-tier';const title=document.createElement('strong');title.textContent='ขั้น '+tier;row.append(title);for(let index=0;index<2;index++){const id=player.weaponLoadout[tier-1][supportWindowKind][index],slot=document.createElement('div');slot.className='support-slot';const select=document.createElement('button');select.className='weapon-skill-cell';select.disabled=player.level<SKILL_MIN_LEVEL[tier]||player.classTier<tier;select.textContent=select.disabled?'Lv.'+SKILL_MIN_LEVEL[tier]+' · ใช้ตราขั้น '+tier:id?WEAPON_SKILLS[id].name+'\nLv.'+player.weaponSkills[id]+(weaponSkillEnabled(id)?'':'\nอาวุธ/Emblem ไม่ตรง'):'เลือก '+supportWindowKind+' ช่อง '+(index+1);select.onclick=()=>pickWeaponSkill(tier,supportWindowKind,index);skillPreview(select,id);slot.append(select);if(id){const detail=document.createElement('button');detail.className='support-info';detail.textContent='รายละเอียด / อัป';detail.onclick=()=>openWeaponSkillDetail(id);slot.append(detail)}row.append(slot)}grid.append(row)}body.append(grid);supportTabs(body);const note=document.createElement('p');note.textContent='ขั้นละ 2 Buff / 2 Passive · เลือกจากอาวุธหลักและ Emblem · ชื่อเดียวกันไม่ซ้อน · ผลส่งข้ามอาวุธ';body.append(note)};
pickWeaponSkill=function(tier,kind,index){ensureBaselineSkills(player);hideUpgradeTooltip();const body=document.createElement('div');body.className='weapon-picker-panel';const tabs=document.createElement('div');tabs.className='weapon-picker-tabs';const list=document.createElement('div');list.className='weapon-picker-rows';let weapon=weaponInHand('main')||validClass().weapons[0];function render(){list.replaceChildren();for(const tab of tabs.children)tab.classList.toggle('selected',tab.dataset.weapon===weapon);const family=Object.keys(BASE_CLASSES).find(k=>BASE_CLASSES[k].weapons.includes(weapon));for(const d of Object.values(WEAPON_SKILLS).filter(d=>d.tier===tier&&d.kind===kind&&(d.weapon===weapon||d.owner===family))){const row=document.createElement('div');row.className='weapon-picker-row';row.tabIndex=0;skillPreview(row,d.id);const icon=document.createElement('span');icon.innerHTML=weaponIcon(weapon);const label=document.createElement('span');label.textContent=d.name;const type=document.createElement('small');type.textContent=(d.owner===family?'ร่วมสาย · ':'เฉพาะอาวุธ · ')+kind.toUpperCase();label.append(type);const rank=document.createElement('strong');rank.textContent=player.weaponSkills[d.id]+'/30';const choose=document.createElement('button');choose.textContent='เลือก';choose.disabled=!weaponSkillEnabled(d.id)||player.weaponLoadout[tier-1][kind].some((id,i)=>i!==index&&id&&WEAPON_SKILLS[id].name===d.name);choose.onclick=()=>{if(equipPooledSkill(d.id,index)){closeModal();openControlWindow('skill')}};row.append(icon,label,rank,choose);list.append(row)}}for(const w of Object.keys(WEAPON_NAMES)){const tab=document.createElement('button');tab.dataset.weapon=w;tab.title=WEAPON_NAMES[w];tab.setAttribute('aria-label',WEAPON_NAMES[w]);tab.innerHTML=weaponIcon(w);tab.onclick=()=>{weapon=w;hideUpgradeTooltip();render()};tabs.append(tab)}body.append(tabs,list);modal('เลือก '+kind.toUpperCase()+' · ขั้น '+tier,body,[['ถอดสกิล',()=>{player.weaponLoadout[tier-1][kind][index]=null;if(kind==='active')stopActiveChannels();supportOnEquipmentChange();save();closeModal();openControlWindow('skill')}],['กลับ',()=>{closeModal();openControlWindow('skill')}]]);render()};
const supportBar=document.createElement('div');supportBar.className='support-buffbar';supportBar.setAttribute('aria-label','Buff ช่อง 1–8');combatBars.append(supportBar);
function supportBuffSlots(){return player.weaponLoadout.flatMap(r=>r.buff)}
for(let i=0;i<8;i++){const b=document.createElement('button');b.id='supportHotbar'+i;b.innerHTML='<span>ว่าง</span><small>'+(i+1)+'</small><em></em>';b.onclick=()=>{const id=supportBuffSlots()[i];if(id)castSupportSkill(id)};supportBar.append(b)}
const supportOldHUD=updateWeaponHUD;updateWeaponHUD=function(){supportOldHUD();supportBuffSlots().forEach((id,i)=>{const b=$('supportHotbar'+i);b.querySelector('span').textContent=id?WEAPON_SKILLS[id].name:'ว่าง';b.querySelector('em').textContent=id&&supportCooldown(id)>0?Math.ceil(supportCooldown(id)):'';b.disabled=!id||!supportSelected(id)||supportCooldown(id)>0;b.title=id?weaponSkillText(id):'เลือก Buff ขั้น '+(Math.floor(i/2)+1)})};
const supportOldBuffHUD=updateBuffHUD;updateBuffHUD=function(){supportOldBuffHUD();for(const e of supportEntries()){if(e.d.kind!=='buff')continue;const tile=document.createElement('div');tile.className='buff-placeholder support-indicator';tile.title=e.d.name;let count='';if(e.d.effect==='orbs')count=Math.min(e.v('count'),Math.floor((e.b.elapsed+1e-8)/15))+' ลูก';if(e.d.effect==='shield')count=e.b.charges+' ครั้ง';if(e.d.effect==='berserk')count=e.b.stacks+' Stack';tile.textContent=(count?count+' · ':'')+Math.ceil(e.b.left)+' วิ';$('buffHUD').append(tile)}};
window.addEventListener('keydown',e=>{if(e.repeat||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||screen!=='play'||paused)return;const match=/^(?:Digit|Numpad)([1-8])$/.exec(e.code);if(match){e.preventDefault();const id=supportBuffSlots()[Number(match[1])-1];if(id)castSupportSkill(id)}});
const mobileBuff=document.createElement('button');mobileBuff.textContent='Buff';mobileBuff.onclick=()=>{const list=document.createElement('div');list.className='support-quick';for(const [i,id]of supportBuffSlots().entries()){const b=document.createElement('button');b.textContent=(i+1)+' · '+(id?WEAPON_SKILLS[id].name:'ว่าง')+(id&&supportCooldown(id)>0?' · '+Math.ceil(supportCooldown(id))+' วิ':'');b.disabled=!id||!supportSelected(id)||supportCooldown(id)>0;b.onclick=()=>{closeModal();castSupportSkill(id)};list.append(b)}modal('ใช้ Buff',list,[])};document.querySelector('.mobile-menu').append(mobileBuff);
